{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "visit_duration_min",
  "per_column": [
    {
      "name": "note_length_chars",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Character length of the note is a generic text feature, but it lies outside visit_duration and can plausibly correlate with visit complexity/length. Weak but legitimate predictor, not a restatement or leak."
    },
    {
      "name": "sentence_count",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Another generic verbosity feature; independent of duration and may weakly track visit complexity. Legitimate but low-signal predictor."
    },
    {
      "name": "medical_term_count",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Count of medical terminology reflects clinical complexity of the encounter, which plausibly drives longer visits. Outside the focus and carries genuine domain signal."
    },
    {
      "name": "comorbidity_count",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Number of comorbidities mentioned is a substantive clinical predictor of visit length; more comorbidities typically require longer visits. Not derivable from duration."
    },
    {
      "name": "action_count",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Count of clinical actions/procedures noted plausibly increases visit time. It is a driver of duration rather than a restatement of it, so a legitimate predictor. Borderline: actions are contemporaneous with the visit, but they are causes of time spent, not a deterministic function of the recorded duration."
    },
    {
      "name": "multi_complaint_flag",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Indicator of multiple presenting complaints is a clear complexity signal that plausibly predicts longer visits. Independent of the focus variable."
    }
  ],
  "n_predictors": 6,
  "predictive_utility": 0.55,
  "rationale": "All six columns lie outside visit_duration_min, none restate or leak it, and each plausibly carries some predictive signal. The strongest domain-grounded features are medical_term_count, comorbidity_count, action_count, and multi_complaint_flag, which capture clinical complexity that genuinely drives visit length. note_length_chars and sentence_count are generic verbosity features with weaker, partly redundant signal. As a set they provide meaningful but moderate predictive leverage beyond the original columns, hence a mid-range utility rather than high."
}
